{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 길가 공영주차장(하역주차구획)에서 승용차를 1시간 반 주차 시 1시간 초과로 주차비 외 추가 요금(가산금) 부과 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "하역주차구획에서의 주차는 계속하여 1시간을 초과하여서는 아니 되므로, 승용차를 1시간 반 세운 것은 1시간을 초과한 경우에 해당한다. 제6조제2항제6호에 따라 제14조제4항 본문을 위반하여 주차한 경우에는 가산금 부과 대상이며, 가산금은 해당 주차요금의 4배 금액으로 주차요금과 함께 부과된다. 따라서 1시간을 넘기면 주차비 외에 추가 요금(가산금)이 붙는다.",
          "b_ids": "주차장:제14조제4항, 주차장:제6조제2항, 주차장:제6조제2항제6호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
